<?php require __DIR__.'/_init.php';header('Content-Type: application/json');try{if($_SERVER['REQUEST_METHOD']!=='POST')throw new RuntimeException('POST required');verify_csrf();if(empty($_FILES['image'])||$_FILES['image']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Choose a valid image.');$f=$_FILES['image'];if($f['size']>5242880)throw new RuntimeException('Maximum image size is 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'][$mime]??null;if(!$ext||!getimagesize($f['tmp_name']))throw new RuntimeException('Only JPG, PNG, WebP and GIF images are allowed.');$dir=dirname(__DIR__).'/public/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Unable to save image.');echo json_encode(['url'=>url('uploads/'.$name)]);}catch(Throwable $e){http_response_code(400);echo json_encode(['error'=>$e->getMessage()]);}